// A counter with "state": the count lives in a closure, like useState.
function createCounter() {
  let count = 0;
  return {
    increment: function () { count = count + 1; },
    value: function () { return count; }
  };
}
const c = createCounter();
c.increment();
c.increment();
c.increment();
console.log(c.value());

